              <section class="imitate-panel"><header><b>独立仿写与输出</b><small>Writing DNA 只校准写法；事实与观点强制来自下方已选知识对象。</small></header><el-select v-model="imitateForm.knowledge_keys" multiple filterable collapse-tags :loading="knowledgeLoading" placeholder="选择取材对象（必选：笔记 / 证据卡 / 批判性审查报告）"><el-option v-for="item in knowledgeOptions" :key="item.value" :label="item.label" :value="item.value" /></el-select><div class="imitate-grid"><el-input v-model="imitateForm.topic" placeholder="新文章题目或议题" /><el-select v-model="imitateForm.genre"><el-option label="深度文章" value="深度文章"/><el-option label="评论" value="评论"/><el-option label="短评" value="短评"/><el-option label="综述" value="综述"/></el-select><el-input-number v-model="imitateForm.length" :min="300" :max="12000" :step="100" /></div><el-input v-model="imitateForm.brief" type="textarea" :rows="2" placeholder="本次立场、素材边界和发布场景"/><el-button type="primary" :loading="generating" :disabled="!imitateForm.topic.trim() || !imitateForm.knowledge_keys.length" @click="runImitation">从已选知识对象生成</el-button>
                <div v-if="currentOutput?.kind==='imitation'" class="writing-result"><header><b>{{ currentOutput.title }}</b><div><el-button v-if="!editingOutput" text size="small" @click="beginEditOutput">编辑</el-button><el-button v-else text size="small" @click="cancelEditOutput">取消</el-button><a :href="writingOutputDownloadUrl(currentOutput.id)">下载 Word</a></div></header><el-alert v-if="freshnessWarning" :type="freshnessType" :closable="false" :title="currentOutput.source_freshness.message"/><template v-if="editingOutput"><el-input v-model="draftTitle" maxlength="255" /><el-input v-model="draftText" type="textarea" :rows="18" maxlength="200000" show-word-limit /><el-button type="primary" :loading="savingOutput" @click="saveOutput">保存并重新生成 Word</el-button></template><article v-else v-html="renderMarkdown(currentOutput.output_text)" /></div>
              </section>
