              <label class="review-field"><span>学科审查镜头</span><el-select v-model="reviewForm.discipline"><el-option label="自动 / 跨学科" value="auto"/><el-option label="社会科学" value="social_science"/><el-option label="人文与文学" value="humanities"/><el-option label="自然科学与生物医学" value="natural_biomedical"/></el-select></label>
              <label class="review-field"><span>目标长度 <small>1,200–20,000 字</small></span><el-input v-model.number="reviewForm.length" type="number" min="1200" max="20000" step="100" inputmode="numeric" /></label>
            </div>
            <div class="review-constraints">
              <label class="review-field"><span>Writing DNA <small>只校准表达，不参与事实判断</small></span><el-select v-model="reviewForm.profile_id" clearable placeholder="可选：选择已就绪 DNA"><el-option v-for="profile in readyProfiles" :key="profile.id" :label="`${profile.name} · v${profile.current_version}`" :value="profile.id" /></el-select></label>
              <label class="tone-switch"><span><b>去 AI 味生成约束</b><small>生成时避开 11 类机械痕迹，不自动二次改稿</small></span><el-switch v-model="reviewForm.ai_tone_constraints" /></label>
            </div>
            <el-button type="primary" size="large" :loading="reviewingLiterature" :disabled="!canGenerateReview" @click="runLiteratureReview">生成多文献综述</el-button>
            <p class="provider-note">所选文献片段会发送给当前配置的写作模型；未选择的库内资料不会进入提示词。</p>
          </section>
          <section class="review-result">
            <StudyEmptyState v-if="!currentOutput||currentOutput.kind!=='literature_review'" title="等待建立综述" description="输出会按主题比较共识、冲突、互补证据、最强反证与研究空白，并保存为可编辑 Word。" />
            <template v-else>
              <header><div><span>证据锚点 {{ currentOutput.audit?.citation_count||0 }} · 覆盖 {{ currentOutput.audit?.cited_book_ids?.length||0 }}/{{ currentOutput.audit?.book_ids?.length||0 }} 篇</span><h3>{{ currentOutput.title }}</h3></div><div><el-button plain @click="sendReviewToTone">送去 AI 味逐条审阅</el-button><a :href="writingOutputDownloadUrl(currentOutput.id)">下载 Word</a></div></header>
              <el-alert v-if="freshnessWarning" :type="freshnessType" :closable="false" :title="currentOutput.source_freshness.message"/>
              <el-alert v-if="currentOutput.audit?.unreferenced_book_ids?.length" type="warning" :closable="false" :title="`有 ${currentOutput.audit.unreferenced_book_ids.length} 篇已选文献未出现在正文锚点中，请人工核对。`" />
              <el-alert v-if="currentOutput.audit?.citation_warning" type="warning" :closable="false" :title="currentOutput.audit.citation_warning" />
              <div class="review-audit"><span>限定：已选文献</span><span>{{ currentOutput.audit?.discipline }}</span><span>{{ currentOutput.audit?.review_type }}</span><span v-if="currentOutput.audit?.dna_version">DNA v{{ currentOutput.audit.dna_version }}</span></div>
              <article class="markdown-body" v-html="renderMarkdown(currentOutput.output_text)" />
            </template>
          </section>
        </div>
      </el-tab-pane>
      <el-tab-pane label="去 AI 味" name="clean">
        <div class="clean-layout">
          <section class="clean-input">
            <header><b>白名单式最小改写</b><small>只处理11类可定位痕迹；结构、事实、数字、引语、链接和限定词保持不变。</small></header>
            <el-select v-model="cleanProfileId" clearable placeholder="可选：使用某个语言 DNA 判断原语体"><el-option v-for="profile in readyProfiles" :key="profile.id" :label="profile.name" :value="profile.id" /></el-select>
            <el-input v-model="cleanText" type="textarea" :rows="16" maxlength="120000" show-word-limit placeholder="粘贴需要处理的文本" />
            <div class="clean-actions"><el-button type="primary" :loading="cleaning" :disabled="!cleanText.trim()" @click="runTextClean">处理文本</el-button><el-upload :show-file-list="false" :auto-upload="false" accept=".docx" :on-change="runDocxClean"><el-button :loading="cleaning">导入 Word 并输出 Word</el-button></el-upload></div>
          </section>
          <section class="clean-output">
            <header><b>输出与审计</b><a v-if="currentOutput?.download_ready" :href="writingOutputDownloadUrl(currentOutput.id)">下载 Word</a></header>
            <StudyEmptyState v-if="!currentOutput||currentOutput.kind!=='ai_tone'" compact title="尚无处理结果" description="未命中白名单的文字会原样保留。" />
            <template v-else><div class="audit-strip"><span>候选 {{ outputChanges.length }} 处</span><span>已选择 {{ acceptedIndexes.length }} 处</span><span>拒绝 {{ currentOutput.audit?.rejected?.length||0 }} 处越界改写</span></div><div v-if="outputChanges.length" class="change-review"><header><b>逐条决定是否采用</b><el-checkbox :model-value="acceptedIndexes.length===outputChanges.length" @change="toggleAllChanges">全选</el-checkbox></header><label v-for="(change,index) in outputChanges" :key="`${change.id}-${index}`"><el-checkbox v-model="acceptedIndexes" :value="index"/><span><del>{{ change.old }}</del><ins>{{ change.new||'（删除）' }}</ins><small>规则 {{ change.rule_ids?.join('、') }}</small></span></label><el-button type="primary" plain :loading="reviewing" @click="applyReviewedChanges">按选择重新生成 Word</el-button></div><el-input v-model="currentOutput.output_text" type="textarea" :rows="12" readonly /></template>
          </section>
        </div>
      </el-tab-pane>
      <el-tab-pane label="写作输出" name="outputs">
        <div class="output-layout">
          <aside class="output-history"><header><b>最近输出</b><el-button text size="small" @click="loadOutputs">刷新</el-button></header><button v-for="item in outputs" :key="item.id" :class="{active:currentOutput?.id===item.id}" @click="openOutput(item.id)"><span><b>{{ item.title }}</b><small>{{ outputKindText(item.kind) }} · {{ item.output_length?.toLocaleString() }} 字</small></span><time>{{ formatDate(item.created_at) }}</time></button><StudyEmptyState v-if="!outputs.length" compact title="尚无写作输出" description="生成或处理稿件后会保存在这里。"/><el-pagination v-if="outputTotal>20" small layout="prev, pager, next" :total="outputTotal" :page-size="20" @current-change="loadOutputs"/></aside>
          <main class="output-detail"><StudyEmptyState v-if="!currentOutput" title="选择一条输出" description="正文按需加载，不在列表中返回完整内容。"/><template v-else><header><div><span>{{ outputKindText(currentOutput.kind) }}</span><h3>{{ currentOutput.title }}</h3></div><div><el-button v-if="currentOutput.kind!=='ai_tone'&&!editingOutput" plain @click="beginEditOutput">编辑</el-button><el-button v-if="currentOutput.kind==='literature_review'" plain @click="sendReviewToTone">送去 AI 味审阅</el-button><el-button v-if="currentOutput.kind==='ai_tone'" plain @click="mode='clean'">逐条审阅</el-button><a v-if="currentOutput.download_ready" :href="writingOutputDownloadUrl(currentOutput.id)">下载 Word</a></div></header><el-alert v-if="freshnessWarning" :type="freshnessType" :closable="false" :title="currentOutput.source_freshness.message"/><div v-if="currentOutput.kind==='ai_tone'&&outputChanges.length" class="history-audit">{{ outputChanges.length }} 项候选修改 · 已采用 {{ currentOutput.audit?.accepted_indexes?.length ?? outputChanges.length }} 项 · 规则 {{ (currentOutput.audit?.rules||[]).join('、') }}</div><template v-if="editingOutput"><el-input v-model="draftTitle"/><el-input v-model="draftText" type="textarea" :rows="22" maxlength="200000" show-word-limit/><div class="edit-actions"><el-button @click="cancelEditOutput">取消</el-button><el-button type="primary" :loading="savingOutput" @click="saveOutput">保存并重新生成 Word</el-button></div></template><article v-else class="markdown-body" v-html="renderMarkdown(currentOutput.output_text)"/></template></main>
        </div>
      </el-tab-pane>
    </el-tabs>
  </component>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { ElDrawer, ElMessage } from 'element-plus'
import { listBooks, listWritingProfiles, getWritingProfile, createWritingProfile, refineWritingProfile, imitateWriting, createLiteratureReview, cleanAiToneText, cleanAiToneDocx, listWritingOutputs, getWritingOutput, updateWritingOutput, reviewWritingOutput, writingOutputDownloadUrl, subscribeTask, listKnowledgeRecords, studyReports } from '../api'
import { notifyTaskSubmitted } from '../stores/taskCenter'
import { renderMarkdown } from '../utils/markdown'
import StudyEmptyState from './StudyEmptyState.vue'

const props=defineProps({ modelValue:Boolean, embedded:{type:Boolean,default:false} })
const emit=defineEmits(['update:modelValue'])
const mode=ref('dna'),profiles=ref([]),profileDetail=ref(null),selectedProfileId=ref(null),selectedRevisionId=ref(null),compareRevisionId=ref(null),creating=ref(false),submitting=ref(false),generating=ref(false),reviewingLiterature=ref(false),cleaning=ref(false)
const bookOptions=ref([]),booksLoading=ref(false),refineBooks=ref([]),removeBookIds=ref([]),refineFeedback=ref(''),cleanProfileId=ref(null),cleanText=ref(''),currentOutput=ref(null)
const knowledgeOptions=ref([]),knowledgeLoading=ref(false)
const outputs=ref([]),outputTotal=ref(0),acceptedIndexes=ref([]),reviewing=ref(false),editingOutput=ref(false),savingOutput=ref(false),draftTitle=ref(''),draftText=ref('')
const profileForm=ref({name:'',target_author:'',book_ids:[],rights_acknowledged:false})
const imitateForm=ref({topic:'',genre:'深度文章',length:1800,brief:'',knowledge_keys:[]})
const reviewForm=ref({title:'',question:'',book_ids:[],review_type:'narrative',discipline:'auto',length:3500,profile_id:null,ai_tone_constraints:true})
const readyProfiles=computed(()=>profiles.value.filter(p=>p.status==='ready'))
const activeRevision=computed(()=>profileDetail.value?.revisions?.find(item=>item.id===selectedRevisionId.value)||profileDetail.value?.revisions?.[0]||null)
const comparisonRevision=computed(()=>profileDetail.value?.revisions?.find(item=>item.id===compareRevisionId.value)||null)
const outputChanges=computed(()=>Array.isArray(currentOutput.value?.audit?.changes)?currentOutput.value.audit.changes:[])
const freshnessWarning=computed(()=>['stale','missing','unknown'].includes(currentOutput.value?.source_freshness?.status))
const freshnessType=computed(()=>currentOutput.value?.source_freshness?.status==='unknown'?'info':'warning')
const canDistill=computed(()=>profileForm.value.name.trim()&&profileForm.value.book_ids.length>=20&&profileForm.value.rights_acknowledged)
const canGenerateReview=computed(()=>reviewForm.value.title.trim().length>=2&&reviewForm.value.question.trim().length>=4&&reviewForm.value.book_ids.length>=2)
const statusText=s=>({pending:'排队中',running:'蒸馏中',ready:'可使用',failed:'需重试'}[s]||s)
const statusType=s=>({ready:'success',failed:'danger',running:'warning',pending:'info'}[s]||'info')
const outputKindText=kind=>({imitation:'独立新作',literature_review:'多文献综述',ai_tone:'白名单去 AI 味'}[kind]||kind)
const searchBooks=async(q='')=>{booksLoading.value=true;try{const r=await listBooks({status:'ready',q:q.trim()||undefined,page_size:40});const selected=bookOptions.value.filter(b=>profileForm.value.book_ids.includes(b.id)||refineBooks.value.includes(b.id)||reviewForm.value.book_ids.includes(b.id));bookOptions.value=[...new Map([...selected,...r.items].map(b=>[b.id,b])).values()]}finally{booksLoading.value=false}}
const loadProfiles=async()=>{profiles.value=(await listWritingProfiles()).items||[]}
const loadKnowledgeOptions=async()=>{knowledgeLoading.value=true;try{const bookIds=profileDetail.value?.book_ids||[];const [records,reports]=await Promise.all([listKnowledgeRecords({book_ids:bookIds,record_types:['note','evidence'],page_size:100}),studyReports(1,50)]);const objects=(records.items||[]).map(item=>({value:`${item.record_type}:${item.id}`,label:`${item.record_type==='note'?'笔记':'证据卡'}｜${item.title}`}));const reportObjects=(reports.items||[]).filter(item=>(item.book_ids||[]).every(id=>bookIds.includes(id))).map(item=>({value:`report:${item.id}`,label:`批判性审查｜${item.focus||'综合研读'}`}));knowledgeOptions.value=[...reportObjects,...objects];imitateForm.value.knowledge_keys=imitateForm.value.knowledge_keys.filter(key=>knowledgeOptions.value.some(item=>item.value===key))}finally{knowledgeLoading.value=false}}
const openProfile=async id=>{selectedProfileId.value=id;profileDetail.value=await getWritingProfile(id);selectedRevisionId.value=profileDetail.value.revisions?.[0]?.id||null;compareRevisionId.value=null;removeBookIds.value=[];await loadKnowledgeOptions()}
const loadOutputs=async(page=1)=>{const result=await listWritingOutputs({page,page_size:20});outputs.value=result.items||[];outputTotal.value=result.total||0}
const loadAll=async()=>{await Promise.all([loadProfiles(),searchBooks(''),loadOutputs()]);if(selectedProfileId.value)await openProfile(selectedProfileId.value)}
const followTask=(taskId,profileId)=>{notifyTaskSubmitted();subscribeTask(taskId,()=>{}).then(async()=>{await loadProfiles();await openProfile(profileId)}).catch(()=>loadProfiles())}
const createProfile=async()=>{submitting.value=true;try{const r=await createWritingProfile(profileForm.value);creating.value=false;await loadProfiles();await openProfile(r.profile_id);followTask(r.task_id,r.profile_id);ElMessage.success('蒸馏已进入全局任务中心')}catch(e){ElMessage.error(e.message)}finally{submitting.value=false}}
const toggleCorpusRemoval=id=>{removeBookIds.value=removeBookIds.value.includes(id)?removeBookIds.value.filter(value=>value!==id):[...removeBookIds.value,id]}
const refineProfile=async()=>{submitting.value=true;try{const r=await refineWritingProfile(selectedProfileId.value,{book_ids:refineBooks.value,remove_book_ids:removeBookIds.value,feedback:refineFeedback.value});refineBooks.value=[];removeBookIds.value=[];refineFeedback.value='';followTask(r.task_id,r.profile_id);ElMessage.success('新版本已提交，旧版本会保留')}catch(e){ElMessage.error(e.message)}finally{submitting.value=false}}
const prepareOutput=row=>{currentOutput.value=row;editingOutput.value=false;draftTitle.value=row?.title||'';draftText.value=row?.output_text||'';const saved=row?.audit?.accepted_indexes;acceptedIndexes.value=Array.isArray(saved)?[...saved]:outputChanges.value.map((_,index)=>index)}
const runImitation=async()=>{const payload={...imitateForm.value,knowledge_note_ids:[],evidence_card_ids:[],report_ids:[]};for(const key of payload.knowledge_keys){const [type,id]=key.split(':');if(type==='note')payload.knowledge_note_ids.push(Number(id));else if(type==='evidence')payload.evidence_card_ids.push(Number(id));else if(type==='report')payload.report_ids.push(Number(id))}delete payload.knowledge_keys;generating.value=true;try{prepareOutput(await imitateWriting(selectedProfileId.value,payload));await loadOutputs();ElMessage.success('已从选定知识对象生成独立新作与 Word')}catch(e){ElMessage.error(e.message)}finally{generating.value=false}}
const runLiteratureReview=async()=>{reviewForm.value.length=Math.max(1200,Math.min(20000,Number(reviewForm.value.length)||3500));reviewingLiterature.value=true;try{const submitted=await createLiteratureReview({...reviewForm.value,profile_id:reviewForm.value.profile_id||null});notifyTaskSubmitted();const task=await subscribeTask(submitted.task_id,()=>{});if(task.status==='failed'||task.status==='cancelled')throw new Error(task.error||task.message||'综述任务未完成');prepareOutput(await getWritingOutput(task.result.output_id));await loadOutputs();ElMessage.success('多文献综述与证据审计已生成')}catch(e){ElMessage.error(e.message)}finally{reviewingLiterature.value=false}}
const sendReviewToTone=()=>{if(!currentOutput.value?.output_text)return;cleanText.value=currentOutput.value.output_text;cleanProfileId.value=currentOutput.value.profile_id||reviewForm.value.profile_id||null;mode.value='clean';ElMessage.info('已送入去 AI 味审阅区；处理后仍需逐条决定是否采用')}
const runTextClean=async()=>{cleaning.value=true;try{prepareOutput(await cleanAiToneText({text:cleanText.value,title:'去 AI 味稿件',profile_id:cleanProfileId.value||null}));await loadOutputs();ElMessage.success('候选改写已生成，请逐条审阅')}catch(e){ElMessage.error(e.message)}finally{cleaning.value=false}}
const runDocxClean=async file=>{cleaning.value=true;try{prepareOutput(await cleanAiToneDocx(file.raw,cleanProfileId.value));await loadOutputs();ElMessage.success('Word 候选改写已生成，请逐条审阅')}catch(e){ElMessage.error(e.message)}finally{cleaning.value=false}}
const toggleAllChanges=value=>{acceptedIndexes.value=value?outputChanges.value.map((_,index)=>index):[]}
const applyReviewedChanges=async()=>{reviewing.value=true;try{prepareOutput(await reviewWritingOutput(currentOutput.value.id,acceptedIndexes.value));await loadOutputs();ElMessage.success('已按人工选择重新生成 Word')}catch(e){ElMessage.error(e.message)}finally{reviewing.value=false}}
const beginEditOutput=()=>{draftTitle.value=currentOutput.value?.title||'';draftText.value=currentOutput.value?.output_text||'';editingOutput.value=true}
const cancelEditOutput=()=>{editingOutput.value=false}
const saveOutput=async()=>{if(!draftTitle.value.trim()||!draftText.value.trim())return ElMessage.warning('标题和正文不能为空');savingOutput.value=true;try{prepareOutput(await updateWritingOutput(currentOutput.value.id,{title:draftTitle.value,output_text:draftText.value}));await loadOutputs();ElMessage.success('稿件和 Word 已更新')}catch(e){ElMessage.error(e.message)}finally{savingOutput.value=false}}
const openOutput=async id=>{try{prepareOutput(await getWritingOutput(id))}catch(e){ElMessage.error(e.message)}}
const formatDate=value=>value?new Date(value).toLocaleDateString('zh-CN'):'—'
onMounted(()=>{if(props.embedded)loadAll()})
</script>

